'use strict';

// MODULES //

var pow = require( '@stdlib/math/base/special/pow' );


// MAIN //

/**
* Computes the Cartesian power for a double-precision floating-point strided array using alternative indexing semantics.
*
* @param {NonNegativeInteger} N - number of indexed elements
* @param {NonNegativeInteger} k - power
* @param {Float64Array} x - input array
* @param {integer} strideX - stride length
* @param {integer} offsetX - starting index
* @param {Float64Array} out - output array
* @param {integer} strideOut1 - stride length between consecutive output pairs
* @param {integer} strideOut2 - stride length between elements within each output pair
* @param {integer} offsetOut - starting index
* @returns {Float64Array} output array
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var x = new Float64Array( [ 1.0, 2.0 ] );
* var out = new Float64Array( 8 );
*
* dcartesianPower( 2, 2, x, 1, 0, out, 2, 1, 0 );
* // out => <Float64Array>[ 1.0, 1.0, 1.0, 2.0, 2.0, 1.0, 2.0, 2.0 ]
*/
function dcartesianPower( N, k, x, strideX, offsetX, out, strideOut1, strideOut2, offsetOut ) { // eslint-disable-line max-len
	var len;
	var oj;
	var io;
	var ix;
	var i;
	var j;
	var s;
	var t;

	if ( N <= 0 || k <= 0 ) {
		return out;
	}
	len = pow( N, k );
	io = offsetOut;
	for ( i = 0; i < len; i++ ) {
		t = i;
		for ( j = k - 1; j >= 0; j-- ) {
			s = t % N;
			t = ( t - s ) / N;
			ix = offsetX + ( s * strideX );
			oj = io + ( j * strideOut2 );
			out[ oj ] = x[ ix ];
		}
		io += strideOut1;
	}
	return out;
}


// EXPORTS //

module.exports = dcartesianPower;
